import SwiftUI

// MARK: - Create tab (artifact studio)
//
// Ask · Create · Sources (IA revision 2026-07-10). Four creation actions.
// Quiz + Paper are REAL — generated by an open-source Fireworks model
// (gpt-oss-120b) grounded in the collection's sources; see
// api/app/routers/artifacts.py. Audio + Infographic are marked "Soon"
// until their media pipelines land (Audio → Deepgram Aura TTS).

enum ArtifactKind: String, CaseIterable, Identifiable {
    case quiz, paper, audio, info
    var id: String { rawValue }

    var label: String {
        switch self {
        case .audio: return "Audio summary"
        case .info:  return "Infographic"
        case .quiz:  return "Quiz me"
        case .paper: return "Write a paper"
        }
    }

    var icon: String {
        switch self {
        case .audio: return "waveform"
        case .info:  return "chart.line.uptrend.xyaxis"
        case .quiz:  return "checkmark.circle"
        case .paper: return "doc.text"
        }
    }

    /// Backend `kind` for the generate endpoint; nil = not yet available.
    var backendKind: String? {
        switch self {
        case .quiz:  return "quiz"
        case .paper: return "paper"
        case .audio, .info: return nil
        }
    }

    var comingSoon: Bool { backendKind == nil }

    /// Match a server artifact's kind string back to a UI kind.
    static func from(_ raw: String) -> ArtifactKind? { ArtifactKind(rawValue: raw) }
}

struct CreateTabView: View {
    let collection: NexusCollection
    let items: [Item]

    @State private var artifacts: [Artifact] = []
    @State private var creating: ArtifactKind?
    @State private var didLoad = false
    @State private var errorMessage: String?
    @State private var selected: Artifact?

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: NexusSpacing.lg) {
                header

                LazyVGrid(columns: [GridItem(.flexible(), spacing: NexusSpacing.sm), GridItem(.flexible())], spacing: NexusSpacing.sm) {
                    ForEach(ArtifactKind.allCases) { kind in
                        CreateCard(kind: kind, isBusy: creating == kind) {
                            generate(kind)
                        }
                        .disabled(creating != nil || kind.comingSoon)
                    }
                }

                if let kind = creating {
                    generatingBeat(kind)
                }

                if let errorMessage {
                    ErrorInline(message: errorMessage) { self.errorMessage = nil }
                }

                if !artifacts.isEmpty {
                    VStack(alignment: .leading, spacing: NexusSpacing.sm) {
                        Text("IN THIS COLLECTION")
                            .font(.Nexus.overline)
                            .foregroundColor(.Nexus.ghost)
                            .kerning(NexusKerning.wide)
                            .padding(.top, NexusSpacing.sm)

                        ForEach(artifacts) { artifact in
                            Button { selected = artifact } label: {
                                ArtifactRow(artifact: artifact)
                            }
                            .buttonStyle(.plain)
                            .transition(.opacity.combined(with: .move(edge: .top)))
                        }
                    }
                }
            }
            .padding(.horizontal, NexusSpacing.sideGutter)
            .padding(.top, NexusSpacing.lg)
            .padding(.bottom, NexusSpacing.xl)
        }
        .animation(.spring(response: 0.38, dampingFraction: 0.8), value: artifacts)
        .animation(.easeInOut(duration: 0.2), value: creating)
        .task { await loadIfNeeded() }
        .sheet(item: $selected) { artifact in
            ArtifactDetailView(artifact: artifact)
        }
    }

    private var header: some View {
        VStack(alignment: .leading, spacing: NexusSpacing.xs) {
            Text("CREATE")
                .font(.Nexus.overline)
                .foregroundColor(.Nexus.ghost)
                .kerning(NexusKerning.wide)
            Text("Turn this collection into something new.")
                .font(.Nexus.bodySmall)
                .foregroundColor(.Nexus.muted)
        }
    }

    private func generatingBeat(_ kind: ArtifactKind) -> some View {
        HStack(spacing: NexusSpacing.sm) {
            EchoPulseView()
                .frame(width: 28, height: 28)
            Text("Creating \(kind.label.lowercased())…")
                .font(.Nexus.bodySmall)
                .foregroundColor(.Nexus.muted)
        }
        .frame(maxWidth: .infinity, alignment: .center)
        .padding(.top, NexusSpacing.sm)
        .transition(.opacity)
    }

    // MARK: Data

    private func loadIfNeeded() async {
        guard !didLoad else { return }
        didLoad = true
        do {
            let loaded = try await APIClient.shared.fetchArtifacts(in: collection.id)
            await MainActor.run { artifacts = loaded }
        } catch {
            // Non-fatal: an empty studio is a fine default; surface nothing.
        }
    }

    private func generate(_ kind: ArtifactKind) {
        guard creating == nil, let backendKind = kind.backendKind else { return }
        creating = kind
        errorMessage = nil
        Task {
            do {
                let artifact = try await APIClient.shared.createArtifact(kind: backendKind, in: collection.id)
                await MainActor.run {
                    artifacts.insert(artifact, at: 0)
                    creating = nil
                }
            } catch {
                await MainActor.run {
                    creating = nil
                    errorMessage = friendlyError(error, kind: kind)
                }
            }
        }
    }

    private func friendlyError(_ error: Error, kind: ArtifactKind) -> String {
        if case APIError.serverError(422) = error {
            return "Add and process at least one source before creating a \(kind.label.lowercased())."
        }
        return "Couldn't create that just now. Please try again."
    }
}

// MARK: - Creation card

private struct CreateCard: View {
    let kind: ArtifactKind
    let isBusy: Bool
    let action: () -> Void

    @State private var pressed = false

    var body: some View {
        Button(action: action) {
            HStack(spacing: 10) {
                Image(systemName: kind.icon)
                    .font(.system(size: 17, weight: .medium))
                    .foregroundColor(kind.comingSoon ? .Nexus.ghost : .Nexus.accent)
                    .frame(width: 22)
                Text(kind.label)
                    .font(.system(size: 13.5, weight: .semibold))
                    .kerning(-0.2)
                    .foregroundColor(kind.comingSoon ? .Nexus.faint : .Nexus.ink)
                    .lineLimit(1)
                    .minimumScaleFactor(0.8)
                Spacer(minLength: 0)
                if kind.comingSoon {
                    Text("SOON")
                        .font(.system(size: 8, weight: .bold))
                        .kerning(0.5)
                        .foregroundColor(.Nexus.ghost)
                        .padding(.horizontal, 5).padding(.vertical, 2)
                        .background(Color.Nexus.surface2)
                        .clipShape(Capsule())
                        .layoutPriority(1)
                }
            }
            .padding(13)
            .background(Color.Nexus.cardBackground)
            .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
            .overlay(
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .stroke(Color.Nexus.border, lineWidth: NexusBorder.hair)
            )
            .opacity(isBusy ? 0.55 : (kind.comingSoon ? 0.75 : 1))
        }
        .buttonStyle(.plain)
        .scaleEffect(pressed ? NexusScale.pressLight : 1)
        .animation(NexusAnimation.press, value: pressed)
        .onLongPressGesture(minimumDuration: 0, pressing: { if !kind.comingSoon { pressed = $0 } }, perform: {})
    }
}

// MARK: - Inline error

private struct ErrorInline: View {
    let message: String
    let onDismiss: () -> Void

    var body: some View {
        HStack(alignment: .top, spacing: 9) {
            Image(systemName: "exclamationmark.circle.fill")
                .font(.system(size: 14))
                .foregroundColor(.Nexus.destructive)
            Text(message)
                .font(.system(size: 13))
                .foregroundColor(.Nexus.muted)
            Spacer(minLength: 0)
            Button(action: onDismiss) {
                Image(systemName: "xmark").font(.system(size: 11, weight: .semibold)).foregroundColor(.Nexus.faint)
            }
            .buttonStyle(.plain)
        }
        .padding(12)
        .background(Color.Nexus.destructive.opacity(0.06))
        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
    }
}

// MARK: - Artifact row (list card)

private struct ArtifactRow: View {
    let artifact: Artifact

    private var kind: ArtifactKind? { ArtifactKind.from(artifact.kind) }

    private var subtitle: String {
        switch artifact.kind {
        case "quiz":
            let n = artifact.content?.questions?.count ?? 0
            return "\(n) question\(n == 1 ? "" : "s")"
        case "paper":
            let sections = artifact.content?.outline?.count ?? 0
            return sections > 0 ? "Briefing · \(sections) sections" : "Briefing"
        default:
            return ""
        }
    }

    var body: some View {
        HStack(spacing: 12) {
            ZStack {
                RoundedRectangle(cornerRadius: 10, style: .continuous)
                    .fill(Color.Nexus.accent.opacity(0.12))
                    .frame(width: 40, height: 40)
                Image(systemName: kind?.icon ?? "sparkles")
                    .font(.system(size: 16, weight: .semibold))
                    .foregroundColor(.Nexus.accent)
            }
            VStack(alignment: .leading, spacing: 2) {
                Text(artifact.title)
                    .font(.system(size: 14.5, weight: .semibold))
                    .kerning(-0.2)
                    .foregroundColor(.Nexus.ink)
                    .lineLimit(2)
                    .multilineTextAlignment(.leading)
                Text(subtitle)
                    .font(.system(size: 12.5))
                    .foregroundColor(.Nexus.faint)
            }
            Spacer(minLength: 0)
            Image(systemName: "chevron.right")
                .font(.system(size: 13, weight: .semibold))
                .foregroundColor(.Nexus.ghost)
        }
        .padding(.horizontal, 14).padding(.vertical, 12)
        .background(Color.Nexus.cardBackground)
        .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 16, style: .continuous).stroke(Color.Nexus.border, lineWidth: NexusBorder.hair))
    }
}

// MARK: - Artifact detail (routes by kind)

private struct ArtifactDetailView: View {
    let artifact: Artifact
    @Environment(\.dismiss) private var dismiss

    var body: some View {
        NavigationStack {
            ZStack {
                Color.Nexus.pageBackground.ignoresSafeArea()
                content
            }
            .navigationTitle(artifact.kind == "quiz" ? "Quiz" : "Briefing")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button("Done") { dismiss() }
                        .foregroundColor(.Nexus.accent)
                }
            }
        }
    }

    @ViewBuilder
    private var content: some View {
        switch artifact.kind {
        case "quiz":
            if let questions = artifact.content?.questions, !questions.isEmpty {
                QuizPlayerView(questions: questions)
            } else { unavailable }
        case "paper":
            if let md = artifact.content?.markdown, !md.isEmpty {
                PaperReaderView(markdown: md)
            } else { unavailable }
        default:
            unavailable
        }
    }

    private var unavailable: some View {
        VStack {
            Spacer()
            Text("This artifact couldn't be loaded.")
                .font(.Nexus.bodyMedium)
                .foregroundColor(.Nexus.muted)
            Spacer()
        }
    }
}

// MARK: - Paper reader

private struct PaperReaderView: View {
    let markdown: String

    var body: some View {
        ScrollView {
            AssistantMarkdown(content: markdown)
                .padding(.horizontal, NexusSpacing.sideGutter)
                .padding(.vertical, NexusSpacing.lg)
                .frame(maxWidth: .infinity, alignment: .leading)
        }
    }
}

// MARK: - Quiz player (interactive)

private struct QuizPlayerView: View {
    let questions: [QuizQuestion]

    @State private var index = 0
    @State private var picked: Int?
    @State private var score = 0
    @State private var finished = false

    var body: some View {
        if finished {
            resultScreen
        } else {
            questionScreen
        }
    }

    private var current: QuizQuestion { questions[index] }

    private var questionScreen: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: NexusSpacing.lg) {
                // Progress
                VStack(alignment: .leading, spacing: 8) {
                    Text("QUESTION \(index + 1) OF \(questions.count)")
                        .font(.system(size: 11, weight: .semibold))
                        .kerning(0.7)
                        .foregroundColor(.Nexus.faint)
                    GeometryReader { geo in
                        ZStack(alignment: .leading) {
                            Capsule().fill(Color.Nexus.surface2).frame(height: 4)
                            Capsule().fill(Color.Nexus.accent)
                                .frame(width: geo.size.width * CGFloat(index + 1) / CGFloat(questions.count), height: 4)
                        }
                    }
                    .frame(height: 4)
                }

                Text(current.q)
                    .font(.system(size: 19, weight: .semibold))
                    .kerning(-0.3)
                    .foregroundColor(.Nexus.ink)
                    .lineSpacing(3)
                    .fixedSize(horizontal: false, vertical: true)

                VStack(spacing: 10) {
                    ForEach(Array(current.options.enumerated()), id: \.offset) { i, option in
                        OptionRow(
                            text: option,
                            state: optionState(i),
                            action: { pick(i) }
                        )
                        .disabled(picked != nil)
                    }
                }

                if picked != nil {
                    VStack(alignment: .leading, spacing: 6) {
                        Text(picked == current.answer ? "Correct" : "Not quite")
                            .font(.system(size: 13.5, weight: .semibold))
                            .foregroundColor(picked == current.answer ? .Nexus.success : .Nexus.destructive)
                        Text(current.why)
                            .font(.system(size: 14))
                            .foregroundColor(.Nexus.muted)
                            .lineSpacing(3)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(13)
                    .background(Color.Nexus.surface2)
                    .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
                    .transition(.opacity)

                    Button(action: next) {
                        Text(index + 1 == questions.count ? "See results" : "Next question")
                            .font(.system(size: 15.5, weight: .semibold))
                            .foregroundColor(.white)
                            .frame(maxWidth: .infinity)
                            .padding(.vertical, 14)
                            .background(Color.Nexus.accent)
                            .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
                    }
                    .buttonStyle(.plain)
                }
            }
            .padding(.horizontal, NexusSpacing.sideGutter)
            .padding(.vertical, NexusSpacing.lg)
            .animation(.easeInOut(duration: 0.2), value: picked)
        }
    }

    private var resultScreen: some View {
        VStack(spacing: NexusSpacing.md) {
            Spacer()
            Text("\(score)/\(questions.count)")
                .font(.system(size: 52, weight: .bold))
                .foregroundColor(.Nexus.accent)
            Text(scoreMessage)
                .font(.system(size: 16))
                .foregroundColor(.Nexus.muted)
            Button(action: restart) {
                Text("Try again")
                    .font(.system(size: 15, weight: .semibold))
                    .foregroundColor(.Nexus.accent)
                    .padding(.horizontal, 22).padding(.vertical, 12)
                    .overlay(Capsule().stroke(Color.Nexus.accent, lineWidth: 1.5))
            }
            .buttonStyle(.plain)
            .padding(.top, 8)
            Spacer()
        }
        .frame(maxWidth: .infinity)
    }

    private var scoreMessage: String {
        let pct = Double(score) / Double(questions.count)
        switch pct {
        case 1.0: return "Perfect — you know this cold."
        case 0.6...: return "Solid grasp of the material."
        default: return "Worth another read of the sources."
        }
    }

    private func optionState(_ i: Int) -> OptionRow.State {
        guard let picked else { return .idle }
        if i == current.answer { return .correct }
        if i == picked { return .wrong }
        return .dimmed
    }

    private func pick(_ i: Int) {
        guard picked == nil else { return }
        picked = i
        if i == current.answer { score += 1 }
    }

    private func next() {
        if index + 1 == questions.count {
            withAnimation { finished = true }
        } else {
            withAnimation { index += 1; picked = nil }
        }
    }

    private func restart() {
        withAnimation { index = 0; picked = nil; score = 0; finished = false }
    }
}

private struct OptionRow: View {
    enum State { case idle, correct, wrong, dimmed }
    let text: String
    let state: State
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            HStack(spacing: 10) {
                Text(text)
                    .font(.system(size: 14.5, weight: .medium))
                    .foregroundColor(foreground)
                    .multilineTextAlignment(.leading)
                Spacer(minLength: 0)
                if let icon {
                    Image(systemName: icon).font(.system(size: 15, weight: .semibold)).foregroundColor(foreground)
                }
            }
            .padding(.horizontal, 14).padding(.vertical, 13)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(background)
            .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
            .overlay(RoundedRectangle(cornerRadius: 12, style: .continuous).stroke(border, lineWidth: 1.5))
        }
        .buttonStyle(.plain)
        .opacity(state == .dimmed ? 0.5 : 1)
    }

    private var icon: String? {
        switch state {
        case .correct: return "checkmark.circle.fill"
        case .wrong:   return "xmark.circle.fill"
        default:       return nil
        }
    }
    private var foreground: Color {
        switch state {
        case .correct: return .Nexus.success
        case .wrong:   return .Nexus.destructive
        default:       return .Nexus.ink
        }
    }
    private var background: Color {
        switch state {
        case .correct: return Color.Nexus.success.opacity(0.10)
        case .wrong:   return Color.Nexus.destructive.opacity(0.08)
        default:       return Color.Nexus.cardBackground
        }
    }
    private var border: Color {
        switch state {
        case .correct: return Color.Nexus.success.opacity(0.4)
        case .wrong:   return Color.Nexus.destructive.opacity(0.4)
        default:       return Color.Nexus.hair
        }
    }
}
